export const resolveCuts = (rows: readonly ResidueRow[], runId: string): readonly string[] =>
  rows.flatMap((row): readonly string[] => {
    if (row.runId !== runId || row.stage !== CUT_STAGE) return [];
    const parsed = ResidueEntrySchema.safeParse(row.entry);
    if (!parsed.success || parsed.data.anchor.jsonPath !== CUT_ANCHOR) return [];
    return [parsed.data.text];
  });
